```go
package cart

import "errors"

var (
	ErrItemNotFound = errors.New("item not found in cart")
	ErrInvalidQuantity = errors.New("quantity must be positive")
)

type Item struct {
	ID       string
	Name     string
	Price    float64
	Quantity int
}

type ShoppingCart struct {
	items map[string]*Item
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

func (c *ShoppingCart) AddItem(id, name string, price float64, quantity int) error {
	if quantity <= 0 {
		return ErrInvalidQuantity
	}

	if existing, ok := c.items[id]; ok {
		existing.Quantity += quantity
		return nil
	}

	c.items[id] = &Item{
		ID:       id,
		Name:     name,
		Price:    price,
		Quantity: quantity,
	}
	return nil
}

func (c *ShoppingCart) RemoveItem(id string) error {
	if _, ok := c.items[id]; !ok {
		return ErrItemNotFound
	}
	delete(c.items, id)
	return nil
}

func (c *ShoppingCart) UpdateQuantity(id string, quantity int) error {
	if quantity <= 0 {
		return ErrInvalidQuantity
	}

	item, ok := c.items[id]
	if !ok {
		return ErrItemNotFound
	}
	item.Quantity = quantity
	return nil
}

func (c *ShoppingCart) GetItem(id string) (*Item, error) {
	item, ok := c.items[id]
	if !ok {
		return nil, ErrItemNotFound
	}
	return item, nil
}

func (c *ShoppingCart) GetItems() []*Item {
	result := make([]*Item, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, item)
	}
	return result
}

func (c *ShoppingCart) GetTotal() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

func (c *ShoppingCart) GetItemCount() int {
	var count int
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}

func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}
